INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('supun-traders', 'Supun Traders & Distributors (Pvt) Ltd', 'Supun Traders', 'The Group''s original wholesale and retail business, trusted since 1978.', 'Supun Traders is where it all started. Founded in 1978 by Mohamed Fareed, it began as a trading business importing and distributing household goods, and grew into the foundation the Group stands on today. In 1999, his son, current Chairman Mr. Kaleel, took on that legacy and built it into what is now the Supun Group of Companies. Today, Supun Traders remains a trusted wholesaler and retailer of imported and locally manufactured household goods, home appliances, and electronics.', 'Retail & Distribution', '1978', '', '["Founded 1978, the original Supun business","Strong, long-standing supplier relationships","Island-wide wholesale distribution network","Wide range of household goods, appliances & electronics"]', '/uploads/1785481005491-104528024-supun trades.png', '2025-10-13 08:24:21', '2026-07-31 06:56:45', NULL, '0112 433 784', NULL, 'info@supungroup.lk', '01124322232', '["/uploads/1760354877441-363723826-AC9h4npdEfJ5E2-FL26aqat6Pg3JYz0N.jpg","/uploads/1760354877447-910306610-AC9h4nprQ2lSQQsl0WHTLPXUlrrtzawc.jpg","/uploads/1760354877449-290645360-AC9h4noSHuDSbKum_-Rd8T5pFrmoxD9G.jpg"]', 1, '[]', 'https://maps.app.goo.gl/R5d8HLxR5iCWJFGC8');
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('aero-star', 'Aerostar Home Appliances (Pvt) Ltd', 'Aero Star', 'Chrome plating for Sri Lanka''s Camy appliances.', 'Aero Star''s chrome-plating expertise, built to local and international standards, feeds directly into the Camy wall clocks, mixer grinders, and water filters found in homes across Sri Lanka. It''s precision manufacturing most customers never see, but touch every day.', 'Manufacturing', '2016', '', '["Chrome & chrome-plating manufacturing","Manufactures Camy wall clocks, mixer grinders & water filters","Precision manufacturing meeting ISO standards","Supplies core internal components across Camy line"]', '/uploads/1785482634724-751353613-m (2).png', '2025-10-13 08:24:21', '2026-07-31 07:23:54', NULL, '034 2262430', '0342262430', 'aerostarhome@gmail.com', NULL, '[]', 5, '[]', NULL);
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('supun-arcade', 'Supun Arcade Residency (Pvt) Ltd', 'Supun Arcade', 'Luxury city apartment hotel in the heart of Colombo with modern amenities.', 'SUPUN ARCADE RESIDENCY is a luxury city apartment hotel located in the heart of Colombo offering all modern luxury. Fully air-conditioned apartments provide a panoramic ocean view, or a dynamic city view to make the stay memorable. The 40-suite complex is equipped with all the amenities the discerning traveler is looking for today.', 'Hospitality', '', 'https://supunarcaderesidency.com', '["40 luxury suites","Ocean and city views","Prime Colombo location","Modern amenities and services","Fully air-conditioned"]', '/uploads/1785481183178-713193515-Screenshot 2026-07-31 122923.png', '2025-10-13 08:24:21', '2026-07-31 07:02:28', NULL, NULL, '0112 055 040', NULL, NULL, '["/uploads/1785481329582-839841984-WhatsApp%20Image%202025-10-07%20at%2011.29.46_068ece23.jpg","/uploads/1785481329621-568684837-14136673.jpg","/uploads/1785481348126-169751178-13800927.jpg","/uploads/1785481348127-353132488-13801595.jpg","/uploads/1785481348127-400495183-25315553.jpg","/uploads/1785481348127-3833918-13801211.jpg"]', 1, '[{"name":"Booking.com","url":"https://shorturl.at/cMyhW"}]', 'https://maps.app.goo.gl/B5DoY6ZqhckkcgQbA');
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('camy-smart', 'Camy Smart (Pvt) Ltd', 'Camy Smart', 'One of Sri Lanka''s largest SLS-certified helmet manufacturers.', 'Every Camy Smart helmet leaving the factory is SLS certified, meeting Sri Lanka''s official safety standard for motorcycle helmets. What started as a single factory is now one of the largest helmet manufacturers in the country, with a distribution network of more than 250 dealers reaching every corner of the island.', 'Manufacturing', '2017', 'https://camysmart.lk', '["SLS Certified: Sri Lanka''s official safety standard","250+ island-wide distributors","One of Sri Lanka''s largest helmet manufacturers","Continuous impact & safety testing laboratory"]', '/uploads/1785482388651-49277483-camy smart logo.png', '2025-10-13 08:24:21', '2026-07-31 07:19:48', NULL, '+94 112 055 026', NULL, 'info@supungroup.lk', NULL, '["/uploads/1760356688349-191530740-images.jpg"]', 6, '[]', 'https://maps.google.com/?q=Horana+Sri+Lanka');
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('new-camy-smart', 'New Camy Smart (Pvt) Ltd', 'New Camy Smart', 'Non-stick cookware, built with Korean technology.', 'New Camy Smart manufactures Sri Lanka''s leading non-stick cookware, built on highly purified aluminum and finished with ceramic and non-stick coating technology developed in partnership with Korean manufacturing experts.', 'Manufacturing', '2018', '', '["Non-stick & ceramic-coated cookware","Korean technology collaboration","Market-leading local cookware manufacturer","Highly purified aluminum base"]', '/uploads/1785482583725-725560442-m (1).png', '2025-10-13 08:24:21', '2026-07-31 07:23:03', NULL, '011 2418724', '0112418724', 'info@supungroup.lk', NULL, '[]', 8, '[]', NULL);
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('supun-super-centre', 'Supun Super Centre (Pvt) Ltd', 'Supun Super Centre', 'Modern retail center with online platform serving customers worldwide.', 'Strategically located in the heart of Colombo with ample parking provides with an ultimate shopping experience to its customers from products ranging from household utilities to electronics and fragrances. The company focuses equally on developing the right balance in providing the best product to its customer, in terms of price and quality. The latest innovation to super center is the launch of our online platform www.anythingatsupun.lk, customers from anywhere around the world can order/gift our products to anywhere in Sri Lanka.', 'Retail', '', '', '["Prime Colombo location","Wide product range","Online shopping platform","Worldwide ordering capability","Ample parking facilities"]', '/uploads/1785482240652-854734715-Untitled design (2).png', '2025-10-13 08:24:21', '2026-07-31 07:17:20', NULL, NULL, '0112504920', NULL, NULL, '["/uploads/1760355727263-878402201-2021-12-15.jpg","/uploads/1760355727279-406690040-AC9h4npKDs0YS-4Gx8KnF7CsjOT3PpQm.jpg","/uploads/1760355727286-136994171-IMG-20251007-WA0194.jpg","/uploads/1760355727288-425388355-IMG-20251007-WA0195.jpg","/uploads/1760355727288-106977264-IMG-20251007-WA0205.jpg","/uploads/1760355727289-315234918-IMG-20251007-WA0201.jpg","/uploads/1785482240653-419017341-unnamed.webp"]', 3, '[]', 'https://maps.app.goo.gl/kYGdjnqVLLDyfdUf6');
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('supun-aerosoft', 'Supun Aerosoft (Pvt) Ltd', 'Supun Aerosoft / YMAC Smart', 'Sri Lanka''s first PU footwear manufacturer.', 'Supun Aerosoft was the first to bring PU (Polyurethane) manufacturing technology to Sri Lanka''s footwear industry. Producing sandals and shoes for men, women, and children under the YMAC Smart brand, Aerosoft combines local craftsmanship with modern manufacturing in our own factories. In 2025, YMAC Smart became the only Sri Lankan footwear brand featured at the Canton Fair, marking a new chapter of international recognition for the brand.', 'Manufacturing', '2011', '', '["Sri Lanka''s first PU footwear manufacturer","Sandals & shoes for men, women, and children","100% made in our own factories","Only Sri Lankan brand featured at the 2025 Canton Fair"]', '/uploads/1785482138605-676412549-Untitled design (1).png', '2025-10-13 08:24:21', '2026-07-31 07:55:59', NULL, '011 2436390', '0112436390', 'supunaerosoft318@gmail.com', NULL, '["/uploads/1785482138606-133665777-IMG-20251007-WA0267.jpg","/uploads/1785482138607-885768584-IMG-20251007-WA0266.jpg","/uploads/1785482138608-355669929-IMG-20251007-WA0265.jpg"]', 4, '[]', 'https://maps.google.com/?q=Kotahena+Colombo+13');
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('kewr-technologies', 'Kewr Technologies (Pvt) Ltd', 'Kewr Technologies', 'Sri Lanka''s first technology house for automobile and component research and design.', 'Sri Lanka''s 1st technology house, with direct emphasis on automobile and automobile component research and design as an independent Design House. KEWR Technologies is headed by world-class designers and manufacturing engineers with technology transfer programs with Siemens, CARBENCH and other internationally acclaimed institutions for design, prototyping, simulation and verification process to provide a concept to mass-produce automobiles as per client/market requirement with conformity to standards of the local and international regulators.', 'Technology & Design', '', 'https://kewrtech.com', '["World-class design team","Technology partnerships with Siemens & CARBENCH","Complete design to production capability","International standards compliance","Advanced CAD and simulation tools"]', '/uploads/1785484461825-135170541-m (4).png', '2025-10-13 08:24:21', '2026-07-31 07:54:21', NULL, NULL, NULL, NULL, NULL, '[]', 11, '[]', NULL);
INSERT OR REPLACE INTO companies (id, name, shortName, description, fullDescription, industry, established, website, features, imageUrl, createdAt, updatedAt, catalogPdf, phone, hotline, email, faxNumber, gallery, sequence, socialLinks, googleMapsLink) VALUES ('camy-global', 'Camy Global', 'Camy Global', 'Getting Camy products to every corner of the island.', 'Camy Global is the distribution engine that gets Camy products, from helmets and cookware to clocks, appliances, air conditioners, and fans, from the factory floor to retail shelves island-wide.', 'Retail & Distribution', '2018', '', '["Islandwide distribution network","Retail outlet & partner network","Distributes the full range of Camy-branded products","Logistics backbone connecting factories to consumers"]', '/uploads/1785482330197-794007903-m.png', '2025-10-13 08:31:22', '2026-07-31 07:18:50', NULL, '+94 112 055 026', NULL, 'info@supungroup.lk', NULL, '[]', 10, '[]', NULL);
