INSERT OR REPLACE INTO products (id, title, slug, shortDescription, longDescription, imageUrl, price, wholesalePrice, categoryId, isVariable, isActive, createdAt, updatedAt) VALUES (2, 'Camy Smart SLS Motorcycle Helmets', 'camy-smart-sls-motorcycle-helmets', 'SLS Certified motorcycle riding helmets engineered for aerodynamic safety and comfort.', 'Every Camy Smart helmet is SLS certified, meeting Sri Lanka''s official safety standard for motorcycle helmets. Built with high-impact ABS/polycarbonate outer shells moulded by Rodsons with multi-point EPS absorption.', '/uploads/1785482388651-49277483-camy smart logo.png', 6500.0, 5200.0, 2, 0, 1, '2026-08-23 19:33:18', '2026-08-23 19:33:18');
INSERT OR REPLACE INTO products (id, title, slug, shortDescription, longDescription, imageUrl, price, wholesalePrice, categoryId, isVariable, isActive, createdAt, updatedAt) VALUES (3, 'New Camy Smart Non-Stick Cookware Set', 'new-camy-smart-non-stick-cookware', 'Premium non-stick cookware manufactured on purified aluminum with Korean ceramic coating technology.', 'Sri Lanka''s leading non-stick cookware, built on heavy-gauge purified aluminum and finished with Korean non-stick coating technology. Ensures even heat retention and long-lasting durability.', '/uploads/1785482583725-725560442-m (1).png', 8900.0, 7200.0, 3, 0, 1, '2026-08-23 19:33:18', '2026-08-23 19:33:18');
INSERT OR REPLACE INTO products (id, title, slug, shortDescription, longDescription, imageUrl, price, wholesalePrice, categoryId, isVariable, isActive, createdAt, updatedAt) VALUES (4, 'Camy Inverter Air Conditioner', 'camy-inverter-air-conditioner', 'Eco-friendly, energy saving air conditioners made in Sri Lanka by Fuji Industries.', 'Assembled in Sri Lanka with anti-corrosive gold-fin condensers, high efficiency R32 refrigerant, and whisper-quiet operation for residential and commercial cooling.', '/uploads/1760357428290-547294273-IMG-20251007-WA0218.jpg', 135000.0, 118000.0, 5, 0, 1, '2026-08-23 19:33:18', '2026-08-23 19:33:18');
INSERT OR REPLACE INTO products (id, title, slug, shortDescription, longDescription, imageUrl, price, wholesalePrice, categoryId, isVariable, isActive, createdAt, updatedAt) VALUES (5, 'Camy Pure Copper Motor Fans', 'camy-pure-copper-fans', 'Durable ceiling and stand fans built with 100% pure copper winding for tropical conditions.', 'Manufactured in Sri Lanka by Fuji Industries, featuring aerodynamic balanced blades, rust-resistant electro-coating, and high air displacement.', '/uploads/1760357428290-547294273-IMG-20251007-WA0218.jpg', 9500.0, 7800.0, 5, 0, 1, '2026-08-23 19:33:18', '2026-08-23 19:33:18');
INSERT OR REPLACE INTO products (id, title, slug, shortDescription, longDescription, imageUrl, price, wholesalePrice, categoryId, isVariable, isActive, createdAt, updatedAt) VALUES (6, 'Aero Star Multi-Stage Water Filter', 'aero-star-multi-stage-water-filter', 'Hygienic multi-stage water purifiers ensuring safe drinking water for Sri Lankan homes.', 'Precision chrome fittings and food-grade body moulding by Rodsons, eliminating contaminants and heavy sediments while retaining essential minerals.', '/uploads/1785482634724-751353613-m (2).png', 7800.0, 6200.0, 4, 0, 1, '2026-08-23 19:33:18', '2026-08-23 19:33:18');
INSERT OR REPLACE INTO products (id, title, slug, shortDescription, longDescription, imageUrl, price, wholesalePrice, categoryId, isVariable, isActive, createdAt, updatedAt) VALUES (7, 'Aero Star Heavy Duty Mixer Grinder', 'aero-star-heavy-duty-mixer-grinder', 'High-torque stainless steel jar mixer grinders for demanding kitchen tasks.', 'Equipped with high-torque copper motors and stainless steel jars designed specifically to handle tough Sri Lankan spices and daily culinary requirements.', '/uploads/1785482634724-751353613-m (2).png', 14500.0, 11800.0, 4, 0, 1, '2026-08-23 19:33:18', '2026-08-23 19:33:18');
